import { existsSync, readdirSync, realpathSync } from "node:fs";
import { isAbsolute, join, relative, resolve } from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

/** Invoke from the consumer's Electrobun postBuild hook. ESM remains the default. */
export function buildNativeBytecode({ entrypoint, tsconfig }) {
  const enabled = process.env.NATIVE_PIXI_BYTECODE;
  if (enabled === undefined || enabled === "0") return;
  if (enabled !== "1") throw new Error("NATIVE_PIXI_BYTECODE must be 0 or 1");
  if (process.env.ELECTROBUN_OS !== "win" || process.env.ELECTROBUN_ARCH !== "x64") {
    throw new Error("Native bytecode builds currently support Windows x64 only");
  }
  const project = realpathSync(process.cwd());
  const within = path => {
    const result = realpathSync(path), rel = relative(project, result);
    if (!rel || rel.startsWith("..") || isAbsolute(rel)) throw new Error("Bytecode input/output must stay inside the consumer project");
    return result;
  };
  if (!process.env.ELECTROBUN_BUILD_DIR) throw new Error("Bytecode requires an Electrobun postBuild environment");
  const buildRoot = within(resolve(process.env.ELECTROBUN_BUILD_DIR));
  const candidates = readdirSync(buildRoot, { withFileTypes: true }).filter(item => item.isDirectory())
    .map(item => join(buildRoot, item.name)).filter(path => existsSync(join(path, "Resources/app/bun/index.js")));
  if (candidates.length !== 1) throw new Error("Expected one freshly built native Bun application");
  const bundle = within(candidates[0]);
  if (existsSync(join(bundle, "Resources/app.asar"))) throw new Error("Bytecode requires a flat application payload");
  const bun = within(join(bundle, "bin/bun.exe"));
  const probe = spawnSync(bun, ["--version"], { encoding: "utf8", windowsHide: true });
  if (probe.status !== 0 || probe.stdout.trim() !== "1.4.2") throw new Error("Bytecode must be generated by the bundled Bun 1.4.2");
  const builder = fileURLToPath(new URL("./bytecode-builder.ts", import.meta.url));
  const result = spawnSync(bun, [builder, within(resolve(entrypoint)), within(resolve(tsconfig)), bundle, buildRoot], {
    cwd: project, env: process.env, stdio: "inherit", windowsHide: true,
  });
  if (result.error) throw result.error;
  if (result.status !== 0) throw new Error(`Native bytecode generation failed (${result.status})`);
}
